def enrich():
    allq={q['id']:q for qs in QUESTIONS.values() for q in qs}
    maps={'intro':INTRO,'micro':MICRO,'macro':MACRO,'global':GLOBAL}
    for row in LEDGER:
        q=allq[row['id']];fam=row['family'];v=row['variant']-1
        if '-structured-' in fam or fam.startswith('intro-'):
            prefix=fam.split('-')[0];idx=int(fam.rsplit('-',1)[1]);variants=maps[prefix].get(idx)
            if variants:
                evidence,reason=variants[v]
                q['stem']+='\n\nAnswer parts (a)–(c) using the initial scenario. For part (d) only, consider the following additional evidence, which may change an initial assumption.\n\nAdditional application evidence: '+evidence
                label=chr(ord('a')+len(q['parts']))
                p,g=point(label,'Explain how the additional evidence changes or qualifies the economic interpretation in this case.',2,('A1','Identify the economic determinant, constraint or model assumption affected by this evidence, distinguishing it from the conditions used in the initial analysis.'),('R1',reason+' A justified causal link is required for this explanation mark.'))
                q['parts'].append(p);q['markScheme'].append(g);q['marks']+=2
                row['variantEvidence']=evidence;row['variantReasoning']=reason
        elif '-essay-' in fam:
            prefix=fam.split('-')[0];idx=int(fam.rsplit('-',1)[1])-1;evidence,reason=ESSAY[prefix][idx][v]
            q['stem']+='\n\nFor part (b) only, consider this further case condition. If it differs from the initial illustration, use it in place of the initial condition: '+evidence
            q['parts'][-1]['prompt']+=' Explain how this case condition qualifies your judgement, while supporting your wider argument with actual studied examples.'
            q['markScheme'][-1]['steps'].insert(1,{'code':'IND','text':'Variant application: '+reason+' Apply the relevant condition to the example(s) the student uses; the fictional illustration alone does not satisfy the real-world-example strand.'})
            row['variantEvidence']=evidence;row['variantReasoning']=reason
        elif q['questionType']=='data-response':
            evidence,reason=[('The public budget is tight and service providers cannot expand capacity immediately.','Timing, opportunity cost and short-run supply constraints qualify the scale of benefits.'),('Administrative records omit some low-income or remote households.','Eligibility, access and distributional effects should be assessed rather than assuming all intended beneficiaries are reached.'),('The proposal is reviewed after one year using local outcome data.','A reviewable phased approach can adjust to evidence, although measurement and implementation quality still matter.')][v]
            q['stem']+='\n\nA further case detail: '+evidence
            q['markScheme'][-1]['steps'].insert(1,{'code':'IND','text':'Variant-specific evaluation: '+reason})
            row['variantEvidence']=evidence;row['variantReasoning']=reason
        elif q['questionType']=='policy-response':
            evidence,reason=[('Implementation can be phased and audited before nationwide expansion.','Compare a monitored pilot with immediate broad rollout, using the quantitative evidence and acknowledging the cost of delay.'),('The authority has weak enforcement capacity and limited reliable household records.','Simple implementable rules may outperform an administratively demanding optimum; weigh targeting errors and evasion.'),('Benefits arrive with a lag, while some affected households need immediate assistance.','Compare transitional support with the main structural policy, recognizing fiscal cost and avoiding unsupported promises of immediate benefits.')][v]
            q['stem']+='\n\nImplementation evidence: '+evidence
            q['markScheme'][-1]['steps'].insert(1,{'code':'IND','text':'Variant-specific recommendation: '+reason})
            row['variantEvidence']=evidence;row['variantReasoning']=reason
        # Bind each best-fit table to its actual task and variant. In particular,
        # Paper 2's reusable level descriptors must not have only a generic focus.
        for part,scheme in zip(q['parts'],q['markScheme']):
            if 'rubric' not in scheme:
                continue
            focus=part['prompt']
            if row.get('variantEvidence'):
                focus+=' Case condition: '+row['variantEvidence']
            for band in scheme['rubric']['bands']:
                descriptor=band['descriptor'].split(' Focus:',1)[0]
                band['descriptor']=descriptor+' Focus: '+focus
